static inline float pads_xgb_lh_predict(const short* FEAT,const float* THR,const short* LEFT,
    const short* RIGHT,const short* ROOT,int ntree,float inter,const float* median,const float* feat){
  float x[PADS_XGB_LH_NFEAT];
  for(int i=0;i<PADS_XGB_LH_NFEAT;i++){ float v=feat[i]; x[i]=(isnan(v)?median[i]:v); }
  float s=inter;
  for(int t=0;t<ntree;t++){ int i=ROOT[t];
    while(FEAT[i]!=-1) i=(x[FEAT[i]]<THR[i])?LEFT[i]:RIGHT[i];
    s+=THR[i]; }
  return 1.0f/(1.0f+expf(-s));
}
